<?php session_start();require 'koneksi.php';require_admin();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$s=mysqli_prepare($koneksi,"SELECT COUNT(*) transaksi,COALESCE(SUM(total),0) omzet FROM pesanan WHERE DATE(created_at) BETWEEN ? AND ? AND status<>'dibatalkan'");mysqli_stmt_bind_param($s,'ss',$from,$to);mysqli_stmt_execute($s);$sum=mysqli_fetch_assoc(mysqli_stmt_get_result($s));$s=mysqli_prepare($koneksi,"SELECT p.nama_produk,SUM(d.jumlah) qty,SUM(d.jumlah*d.harga) omzet FROM detail_pesanan d JOIN pesanan o ON o.id=d.pesanan_id JOIN produk p ON p.id_produk=d.produk_id WHERE DATE(o.created_at) BETWEEN ? AND ? GROUP BY d.produk_id ORDER BY qty DESC");mysqli_stmt_bind_param($s,'ss',$from,$to);mysqli_stmt_execute($s);$q=mysqli_stmt_get_result($s);$title='Laporan';require 'header.php';?><h2>Laporan Penjualan</h2><form class="card actions"><label>Dari <input type="date" name="from" value="<?=e($from)?>"></label><label>Sampai <input type="date" name="to" value="<?=e($to)?>"></label><button class="btn">Filter</button></form><div class="stats"><div class="stat">Jumlah transaksi<b><?=$sum['transaksi']?></b></div><div class="stat">Omzet<b><?=rupiah($sum['omzet'])?></b></div></div><div class="table-wrap"><table><tr><th>Produk</th><th>Terjual</th><th>Omzet</th></tr><?php while($r=mysqli_fetch_assoc($q)):?><tr><td><?=e($r['nama_produk'])?></td><td><?=$r['qty']?></td><td><?=rupiah($r['omzet'])?></td></tr><?php endwhile;?></table></div><?php require 'footer.php';?>
